/bin/zsh -lc "cat > src/orchestration/onErrorCause.test.ts <<'EOF'
import {createChatOrchestrator} from './chatOrchestrator.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {AIProvider, MessageChunk} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';

describe('non-Error rejection', () => {
  it('preserves the rejection as the hook error cause and caller rejection [specs/hal-engine-config-hooks/spec.md#8]', async () => {
    const reason = {code: 503};
    const provider: AIProvider = {
      // eslint-disable-next-line require-yield
      async *sendMessage(): AsyncGenerator<MessageChunk> {
        throw reason;
      },
      async generateStructured<T>(): Promise<T> {
        return {} as T;
      },
    };
    const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
    let received: Error | undefined;
    const orchestrator = createChatOrchestrator(provider, new PromptBuilder({identity: 'test'}), undefined, {
      hooks: {onError: async (_session, error) => void (received = error)},
    });
    const outcome = await orchestrator.processMessage(session).then(
      () => ({rejected: false, value: undefined}),
      (value: unknown) => ({rejected: true, value})
    );

    expect({isError: received instanceof Error, cause: received?.cause, outcome}).toEqual({
      isError: true,
      cause: reason,
      outcome: {rejected: true, value: reason},
    });
  });
});
EOF
 timeout 300 node --experimental-vm-modules node_modules/jest/bin/jest.js src/orchestration/onErrorCause.test.ts --runInBand"
